// Tests for the doctor's summary (src/doctor-summary.js): the weekly private medical conference draft and the
// sections of "Message the doctor". The week of the NASA-style review (PO-7) must be in it: a 10 of 10 symptom,
// zolpidem with promethazine, 10 ibuprofen tablets in a day, and exercise, the reaction test and the eye checks.
// Run: npm test (Node 18+). Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createMachine } from '../src/engine.js';
import { CELLS, CREW, SHIP } from '../src/config.js';
import { exampleFlight, MISSION } from '../src/demo-crew.js';
import { exampleEarlierRuns } from '../src/reaction-test.js';
import { RULES } from '../src/state-levels.js';
import { eventProblem } from '../src/security.js';
import { pmcDraft, doctorSections, weekFindings, vitalLines, eyeLines, reactionLines, symptomLines, medicineLines, SUMMARY_RULES, VITALS } from '../src/doctor-summary.js';

const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;
const NOW = new Date('2026-11-15T12:00:00Z');
const at = (hoursAgo) => new Date(NOW.getTime() - hoursAgo * HOUR).toISOString();
const MED = CELLS.find((c) => c.indicator === 'medicines');
const kit = (key, amount, extra = {}) => { const k = MED.kit.find((x) => x.key === key); return { medicine: k.key, name: k.name, strength: k.strength, amount, unit: k.unit, ...extra }; };
const STATE = { aiWorks: true, doctorOnBoard: false, linkToEarth: true };
const MISSION_NOW = { launch: '2026-06-01T12:00:00Z', today: NOW.toISOString(), landing: '2026-12-10T12:00:00Z' };

// A machine with the readings given as [hoursAgo, indicator, value, person?].
function machineWith(rows, mission = MISSION_NOW) {
  const m = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: STATE, mission });
  for (const [h, indicator, value, person = 'crew-1'] of [...rows].sort((a, b) => b[0] - a[0])) m.receive({ person, source: 'test', indicator, value, time: at(h) });
  return m;
}
const inputOf = (m, extra = {}) => ({ name: 'Tom', flightDay: 'flight day 167', now: NOW, get: (ind) => m.history('crew-1', ind), co2: m.history('ship', 'co2'), runs: [], nightHours: RULES.kitNightHours, flagged: [], ...extra });

// The week the review describes, with a little of everything else.
const REVIEW_WEEK = [
  [30, 'symptoms', { symptom: 'other', severity: 10, note: 'chest pain' }],
  [5, 'symptoms', { symptom: 'headache', severity: 5 }],
  [20, 'medicines', kit('zolpidem', 1)],
  [18, 'medicines', kit('promethazine', 1)],
  ...[16, 12, 8, 4, 1].map((h) => [h, 'medicines', kit('ibuprofen', 2)]),
  ...[1, 2, 3, 4, 5, 6].map((d) => [d * 24 + 3, 'exercise', 80 + d]),
  [26, 'visionCheck', 'vision changed'],
  [50, 'octChange', 24],
  ...[1, 2, 3, 4, 5, 6, 7].map((d) => [d * 24 - 6, 'pulse', 60 + d]),
  [10, 'co2', 3.4, 'ship'], [34, 'co2', 2.6, 'ship'], [58, 'co2', 2.2, 'ship'],
];
const RUNS = [
  { time: '2026-05-01T09:00:00Z', median: 300, lapses: 1, falseStarts: 0, mode: 'full', beforeFlight: true },
  { time: '2026-05-20T09:00:00Z', median: 310, lapses: 2, falseStarts: 1, mode: 'full', beforeFlight: true },
  { time: at(28), median: 352, lapses: 4, falseStarts: 1, mode: 'full', beforeFlight: false },
];

test('the review week: the weekly draft holds the 10 of 10 symptom, the medicines with both kit list findings, exercise, the reaction test and the eyes', () => {
  const text = pmcDraft(inputOf(machineWith(REVIEW_WEEK), { runs: RUNS }));
  assert.match(text, /Something else, 10 of 10: chest pain/);
  assert.match(text, /Zolpidem 10 mg, 1 tablet/);
  assert.match(text, /Promethazine 25 mg, 1 tablet/);
  assert.match(text, /Ibuprofen 400 mg, 10 tablets in 5 entries/);
  assert.match(text, /Kit list: Ibuprofen 400 mg, 10 tablets within 24 hours.*"No more than 8 tablets every 24 hours\. Take with food\."/);
  assert.match(text, /Kit list: Zolpidem 10 mg \(GMT [^)]+\) and Promethazine 25 mg \(GMT [^)]+\), within 12 hours of each other/);
  assert.match(text, /- Exercise: 84 minutes a day on average over 6 days, from 81 to 86/);
  assert.match(text, /- Reaction test, GMT \d+\/\d\d:\d\d, 3 minutes: median 352 ms, 4 lapses, 1 false start; slower than my runs from before flight \(median 305 ms, 2 runs\)\./);
  assert.match(text, /- Eye self-check \(SANS\): "Vision changed"/);
  assert.match(text, /- Retinal thickness change \(OCT\), GMT [^:]+:\d\d, 2 days ago: \+24 µm, at or above 20 µm, NASA's earliest indication of SANS \(a draft line here\)\./);
  assert.match(text, /^For my private medical conference\. Tom, flight day 167, the last 7 days:/);
  assert.ok(text.endsWith('What I want to talk about:\n'), 'room for the person\'s own words at the end');
});

test('the private logs come under their own heading, after everything else and before the person\'s own words', () => {
  const text = pmcDraft(inputOf(machineWith(REVIEW_WEEK), { runs: RUNS, flagged: ['Medicines taken (attention)'] }));
  const head = text.indexOf('From my private log of the last 7 days:');
  assert.ok(head > 0);
  assert.ok(text.indexOf('- Flagged by the program: Medicines taken (attention).') < head);
  assert.ok(head < text.indexOf('What I want to talk about:'));
  const above = text.slice(0, head);
  for (const word of ['Symptom:', 'Medicine:', 'Kit list:', 'chest pain']) assert.ok(!above.includes(word), `${word} only under the heading`);
  // With no symptom or medicine in the week there is no private heading at all.
  assert.ok(!pmcDraft(inputOf(machineWith([[3, 'pulse', 70]]))).includes('From my private log'));
});

test('a logged headache carries the cabin CO2 before it: the latest reading, the 7-day average and NASA\'s limit', () => {
  const lines = symptomLines((ind) => machineWith(REVIEW_WEEK).history('crew-1', ind), NOW.getTime() - 7 * DAY, NOW.getTime(), { co2: machineWith(REVIEW_WEEK).history('ship', 'co2') });
  const ache = lines.find((l) => l.includes('Headache'));
  assert.match(ache, /Headache, 5 of 10, GMT \d+\/\d\d:\d\d; cabin CO2 before it 3\.4 mmHg \(latest, GMT \d+\/\d\d:\d\d, 5 h before\), 7-day average 2\.7 mmHg; NASA's limit is 3 mmHg as a one-hour average\./);
  assert.ok(!lines.find((l) => l.includes('chest pain')).includes('CO2'), 'only a headache gets the cabin CO2');
});

test('the numbers part keeps the old summary\'s form, says "1 reading" for one, and leaves out what was not measured', () => {
  const m = machineWith([[3, 'pulse', 70], [27, 'pulse', 104], [5, 'spo2', 97], [6, 'bp', { sys: 118, dia: 76 }]]);
  const since = NOW.getTime() - 7 * DAY;
  const lines = vitalLines((ind) => m.history('crew-1', ind), since, NOW.getTime());
  assert.deepEqual(lines, [
    '- Heart rate: 2 readings, average 87 bpm, from 70 to 104, some outside the normal range.',
    '- Blood pressure: 1 reading, 118/76 mmHg.',
    '- Blood oxygen (SpO2): 1 reading, 97 %.',
  ]);
  assert.deepEqual(VITALS, ['pulse', 'bp', 'spo2', 'temp', 'resp', 'sleep', 'fluid']);
});

test('kit list findings over the week: one per run of 24 hours past a limit with its largest total, each pair once, nothing from before the week', () => {
  const m = machineWith([
    ...[200, 199, 198, 197, 196].map((h) => [h, 'medicines', kit('ibuprofen', 2)]), // 10 tablets, 8 days ago: outside the week
    ...[100, 99, 98, 97, 96].map((h) => [h, 'medicines', kit('ibuprofen', 2)]), // 10 tablets about 4 days ago
    ...[30, 29, 28, 27, 26].map((h) => [h, 'medicines', kit('ibuprofen', 2)]), // 10 tablets yesterday
    [10, 'medicines', kit('melatonin', 1)], [9, 'medicines', kit('meclizine', 1)],
  ]);
  const found = weekFindings((ind) => m.history('crew-1', ind), NOW.getTime() - 7 * DAY, NOW.getTime(), { nightHours: RULES.kitNightHours });
  const max = found.filter((f) => f.rule === 'max');
  assert.equal(max.length, 2, 'two separate days over the limit');
  assert.ok(max.every((f) => f.total === 10 && f.medicine === 'ibuprofen'));
  const night = found.filter((f) => f.rule === 'night');
  assert.deepEqual(night.map((f) => f.medicines), [['melatonin', 'meclizine']]);
  // A medicine taken earlier than logged counts at the time it was taken.
  const late = machineWith([[1, 'medicines', kit('zolpidem', 1)], [1, 'medicines', kit('promethazine', 1, { takenAt: at(30) })]]);
  assert.deepEqual(weekFindings((ind) => late.history('crew-1', ind), NOW.getTime() - 7 * DAY, NOW.getTime(), { nightHours: RULES.kitNightHours }), [], '29 hours apart is not one night');
});

test('Message the doctor: all sections from Today, only the measure\'s own from its page, none for other measures', () => {
  const input = inputOf(machineWith(REVIEW_WEEK), { runs: RUNS });
  const all = doctorSections(input).join('\n');
  for (const part of ['My last 7 days:', '- Exercise:', '- Reaction test,', '- Eye self-check', '- Retinal thickness change', 'From my private log of the last 7 days:', 'chest pain', 'Zolpidem', 'Kit list:']) assert.ok(all.includes(part), part);
  assert.ok(!all.includes('Heart rate'), 'the message keeps to the flagged items and the week, not every number');
  const sym = doctorSections(input, { indicator: 'symptoms' }).join('\n');
  assert.ok(sym.includes('chest pain') && sym.includes('cabin CO2') && !sym.includes('Medicine:') && !sym.includes('Exercise'));
  const med = doctorSections(input, { indicator: 'medicines' }).join('\n');
  assert.ok(med.includes('Medicine:') && med.includes('Kit list:') && !med.includes('Symptom:'));
  assert.match(doctorSections(input, { indicator: 'reaction' }).join('\n'), /median 352 ms/);
  for (const ind of ['visionCheck', 'octChange', 'octScan']) assert.match(doctorSections(input, { indicator: ind }).join('\n'), /Eye self-check/, ind);
  assert.match(doctorSections(input, { indicator: 'exercise' }).join('\n'), /- Exercise:/);
  for (const ind of ['pulse', 'bp', 'co2', 'hearing']) assert.deepEqual(doctorSections(input, { indicator: ind }), [], ind);
});

test('what a flagged item already says is left out of the private part, so the message names it once', () => {
  const m = machineWith(REVIEW_WEEK);
  const input = inputOf(m, { runs: RUNS });
  const chest = m.history('crew-1', 'symptoms').find((x) => x.value.symptom === 'other');
  const night = weekFindings(input.get, NOW.getTime() - 7 * DAY, NOW.getTime(), { nightHours: RULES.kitNightHours }).filter((f) => f.rule === 'night');
  const text = doctorSections(input, { skip: { symptoms: [chest.time], findings: night } }).join('\n');
  assert.ok(!text.includes('chest pain'));
  assert.ok(!text.includes('within 12 hours of each other'));
  assert.ok(text.includes('Headache, 5 of 10') && text.includes('10 tablets within 24 hours'));
});

test('reaction tests: compared with the person\'s own runs before flight, a demo only with demos, the first run says so', () => {
  const since = NOW.getTime() - 7 * DAY;
  const runs = [...RUNS, { time: at(3), median: 290, mode: 'demo', lapses: 0, falseStarts: 0 }];
  const lines = reactionLines(runs, since, NOW.getTime());
  assert.match(lines[0], /30 seconds: median 290 ms, 0 lapses, 0 false starts; nothing of my own to compare with yet\./);
  assert.match(lines[1], /slower than my runs from before flight \(median 305 ms, 2 runs\)/);
  // The made-up example runs say that they are made up.
  const ex = reactionLines([...exampleEarlierRuns(MISSION_NOW.launch), RUNS[2]], since, NOW.getTime());
  assert.match(ex[0], /the made-up example runs from before flight/);
  assert.deepEqual(reactionLines([RUNS[0]], since, NOW.getTime()), [], 'no run in the week, no line');
});

test('the eyes: the answers of the week, or the last ones within 60 days with their age, and nothing older', () => {
  const since = NOW.getTime() - 7 * DAY;
  const m = machineWith([[40 * 24, 'visionCheck', 'no change'], [3 * 24, 'octChange', 8], [70 * 24, 'octChange', 30]]);
  const lines = eyeLines((ind) => m.history('crew-1', ind), since, NOW.getTime());
  assert.match(lines[0], /^- Eye self-check \(SANS\), the last one, GMT \d+\/\d\d:\d\d, 40 days ago: "No change"\.$/);
  assert.match(lines[1], /\+8 µm, below NASA's 20 µm earliest indication of SANS/);
  const old = machineWith([[70 * 24, 'visionCheck', 'grid changed'], [70 * 24, 'octChange', 30]]);
  assert.deepEqual(eyeLines((ind) => old.history('crew-1', ind), since, NOW.getTime()), []);
  assert.match(pmcDraft(inputOf(old)), /- Nothing logged in these days: exercise minutes, a reaction test, an eye self-check or OCT result\./);
  assert.match(pmcDraft(inputOf(machineWith([[48, 'octChange', 60]]))), /at or above 55 µm, NASA's clinically concerning SANS/);
});

test('a heavy week stays short enough to send: at most so many lines of each kind, the rest counted', () => {
  const rows = [];
  for (let i = 0; i < 30; i += 1) rows.push([2 + i * 5, 'symptoms', { symptom: 'backPain', severity: 3, note: 'lower back, after the treadmill session' }]);
  for (let i = 0; i < 12; i += 1) rows.push([3 + i * 7, 'medicines', { medicine: 'other', name: `Test medicine ${i}`, amount: 1 }]);
  for (let i = 0; i < 40; i += 1) rows.push([1 + i * 4, 'medicines', kit('acetaminophen', 2)]);
  const input = inputOf(machineWith(rows));
  const text = pmcDraft(input);
  assert.match(text, /- And 20 more symptom entries\./);
  assert.match(text, /- And \d+ more medicines?\./);
  assert.ok(text.length <= 6000, `${text.length} characters for the conference summary`);
  assert.ok(doctorSections(input).join('\n').length <= 4000, 'the message part fits the 4,000 characters a message can carry');
  assert.equal(SUMMARY_RULES.draft, true);
  // The server takes the draft as the conference summary it is.
  const e = { v: 1, kind: 'report', time: NOW.toISOString(), person: 'crew-1', state: STATE, report: { to: 'doctor-earth', text, topic: 'pmc' } };
  assert.equal(eventProblem(e, { now: NOW.getTime() }), null);
});

test('medicines: one line each, taken earlier than logged counts at that time, another medicine by its name', () => {
  const m = machineWith([[2, 'medicines', kit('melatonin', 0.5, { takenAt: at(9) })], [4, 'medicines', { medicine: 'other', name: 'Eye drops', amount: 1, unit: 'dose' }]]);
  const lines = medicineLines((ind) => m.history('crew-1', ind), NOW.getTime() - 7 * DAY, NOW.getTime());
  assert.deepEqual(lines.map((l) => l.replace(/GMT \d+\/\d\d:\d\d/g, 'GMT t')), ['- Medicine: Eye drops, 1 dose, GMT t.', '- Medicine: Melatonin 3 mg, half a tablet, GMT t.']);
});

test('the example flight: the draft says that it holds made-up data, and Tom\'s week has his exercise, eyes and numbers', () => {
  const m = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: STATE, mission: MISSION });
  for (const ev of exampleFlight(CREW)) if (ev.kind === 'reading') m.receive({ ...ev.reading, person: ev.person, time: ev.time, example: Boolean(ev.example) });
  const text = pmcDraft({ ...inputOf(m), now: new Date(MISSION.today), runs: exampleEarlierRuns(MISSION.launch) });
  assert.match(text, /Note: this summary includes made-up example data \(the example flight is on\)\./);
  for (const part of ['- Heart rate:', '- Exercise:', '- Eye self-check (SANS), the last one', '- Retinal thickness change (OCT)', '- Nothing logged in these days: a reaction test.']) assert.ok(text.includes(part), part);
});

test('no long dashes in the files of this change', () => {
  const dashes = new RegExp(`[${String.fromCharCode(0x2013, 0x2014)}]`);
  for (const f of ['src/doctor-summary.js', 'src/nasa-rules.js', 'tests/summary.test.js', 'tests/nasa-rules.test.js']) {
    assert.ok(!dashes.test(readFileSync(new URL(`../${f}`, import.meta.url), 'utf8')), f);
  }
});
